import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLES = ['임직원', '시스템 관리자', '근태 담당자'];
const STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];
const TRIP_CATEGORIES = ['출장', '외근'];
// 가정: 취소 가능 상태의 구체 범위는 결재 진행 상태 기준이라 했으나 목록이 없어 아직 결재가 끝나지 않은 상태로 정한다
const CANCELABLE_STATUSES = ['기안', '결재대기', '진행중'];
// 가정: 상신 직후 결재 진행 상태, 취소 뒤 상태
const INITIAL_STATUS = '결재대기';
const CANCELED_STATUS = '회수';
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const ID_PATTERN = /^\d+$/;

function invalid(message: string): ApiError {
  return new ApiError(422, 'ATTENDANCE_REQUEST_INVALID', message);
}

function optionalText(value: unknown, max: number, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || value.length > max) {
    throw invalid(label + ' 값이 올바르지 않습니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr01801Controller {
  @Get('/attendance-requests')
  async listAttendanceRequests(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '시스템 관리자', '근태 담당자');
    const q = checks.queryOf(req.query);
    const page = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    const size = q['size'] === undefined || q['size'] === '' ? 20 : Number(q['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 크기가 올바르지 않습니다.');
    }
    const pageSize = Math.min(size, 200);
    const conditions: string[] = [];
    const params: Record<string, unknown> = {};
    const employeeId = q['employeeId'];
    if (employeeId !== undefined && employeeId !== '') {
      if (!ID_PATTERN.test(String(employeeId))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '신청자 값이 올바르지 않습니다.');
      }
      conditions.push('employee_id = CAST(:employeeId AS bigint)');
      params.employeeId = String(employeeId);
    }
    const attendanceTypeId = q['attendanceTypeId'];
    if (attendanceTypeId !== undefined && attendanceTypeId !== '') {
      if (!ID_PATTERN.test(String(attendanceTypeId))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '근태항목 값이 올바르지 않습니다.');
      }
      conditions.push('attendance_type_id = CAST(:attendanceTypeId AS bigint)');
      params.attendanceTypeId = String(attendanceTypeId);
    }
    const approvalStatus = q['approvalStatus'];
    if (approvalStatus !== undefined && approvalStatus !== '') {
      if (typeof approvalStatus !== 'string' || !STATUSES.includes(approvalStatus)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '결재 진행 상태 값이 올바르지 않습니다.');
      }
      conditions.push('approval_status = :approvalStatus');
      params.approvalStatus = approvalStatus;
    }
    const where = conditions.length > 0 ? 'WHERE ' + conditions.join(' AND ') : '';
    return transaction(async (db) => {
      const countRows = await db.query('SELECT COUNT(*) AS "total" FROM attendance_request ' + where, params);
      const rows = await db.query(
        'SELECT attendance_request_id AS "attendanceRequestId", employee_id AS "employeeId", attendance_type_id AS "attendanceTypeId", '
          + 'start_date AS "startDate", end_date AS "endDate", reason AS "reason", approval_status AS "approvalStatus" '
          + 'FROM attendance_request ' + where
          + ' ORDER BY attendance_request_id DESC LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        { ...params, size: pageSize, offset: page * pageSize },
      );
      return { items: rows, page, size: pageSize, total: Number(countRows[0]['total']) };
    });
  }

  @Post('/attendance-requests')
  @HttpCode(200)
  async createAttendanceRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '시스템 관리자', '근태 담당자');
    const data = checks.inputOf(req.body);
    const attendanceTypeId = data['attendanceTypeId'];
    if (attendanceTypeId === undefined || attendanceTypeId === null || !ID_PATTERN.test(String(attendanceTypeId))) {
      throw invalid('근태항목을 선택해 주세요.');
    }
    const startDate = data['startDate'];
    const endDate = data['endDate'];
    if (typeof startDate !== 'string' || !DATE_PATTERN.test(startDate)) {
      throw invalid('시작일을 입력해 주세요.');
    }
    if (typeof endDate !== 'string' || !DATE_PATTERN.test(endDate)) {
      throw invalid('종료일을 입력해 주세요.');
    }
    const reason = optionalText(data['reason'], 1000, '사유');
    const changedWorkTime = optionalText(data['changedWorkTime'], 100, '변경 근무시간');
    const tripCategory = optionalText(data['tripCategory'], 20, '출장·외근 구분');
    const tripPlace = optionalText(data['tripPlace'], 200, '장소');
    if (tripCategory !== null && !TRIP_CATEGORIES.includes(tripCategory)) {
      throw invalid('출장·외근 구분은 출장 또는 외근이어야 합니다.');
    }
    return transaction(async (db) => {
      const types = await db.query(
        'SELECT use_yn AS "useYn" FROM attendance_type WHERE attendance_type_id = CAST(:typeId AS bigint)',
        { typeId: String(attendanceTypeId) },
      );
      if (types.length === 0 || types[0]['useYn'] !== '사용') {
        throw invalid('사용할 수 있는 근태항목이 아닙니다.');
      }
      const order = await db.query(
        'SELECT (CAST(:startDate AS date) <= CAST(:endDate AS date)) AS "ok"',
        { startDate, endDate },
      );
      if (order[0]['ok'] !== true) {
        throw invalid('종료일은 시작일보다 빠를 수 없습니다.');
      }
      const rows = await db.query(
        'INSERT INTO attendance_request (employee_id, attendance_type_id, start_date, end_date, reason, changed_work_time, trip_category, trip_place, approval_status, created_at, updated_at) '
          + 'VALUES (CAST(:userId AS bigint), CAST(:typeId AS bigint), CAST(:startDate AS date), CAST(:endDate AS date), :reason, :changedWorkTime, :tripCategory, :tripPlace, :status, now(), now()) '
          + 'RETURNING attendance_request_id AS "attendanceRequestId", approval_status AS "approvalStatus"',
        {
          userId: user.id,
          typeId: String(attendanceTypeId),
          startDate,
          endDate,
          reason,
          changedWorkTime,
          tripCategory,
          tripPlace,
          status: INITIAL_STATUS,
        },
      );
      return rows[0];
    });
  }

  @Post('/attendance-requests/:attendanceRequestId/cancel')
  @HttpCode(200)
  async cancelAttendanceRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '시스템 관리자', '근태 담당자');
    const id = req.params['attendanceRequestId'];
    if (!ID_PATTERN.test(id)) {
      throw new ApiError(404, 'ATTENDANCE_REQUEST_NOT_FOUND', '근태 신청을 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM attendance_request WHERE attendance_request_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_REQUEST_NOT_FOUND', '근태 신청을 찾을 수 없습니다.');
      }
      if (!CANCELABLE_STATUSES.includes(String(rows[0]['approvalStatus']))) {
        throw new ApiError(409, 'ATTENDANCE_REQUEST_NOT_CANCELABLE', '취소할 수 없는 결재 상태입니다.');
      }
      const updated = await db.query(
        'UPDATE attendance_request SET approval_status = :status, updated_at = now() WHERE attendance_request_id = CAST(:id AS bigint) '
          + 'RETURNING attendance_request_id AS "attendanceRequestId", approval_status AS "approvalStatus"',
        { id, status: CANCELED_STATUS },
      );
      return updated[0];
    });
  }
}

