import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];
const CANCELABLE = ['기안', '결재대기', '진행중'];
const SIZE = 20;

export default function FnSfr01801Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>({});
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [form, setForm] = useState<Row>({});

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/attendance-requests', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );
  const items = data ? data.items : [];
  const countOf = (status: string) => items.filter((r) => r['approvalStatus'] === status).length;

  const search = () => {
    setPage(0);
    setApplied({ ...draft });
  };
  const reset = () => {
    setDraft({});
    setPage(0);
    setApplied({});
  };
  const openCreate = () => {
    setForm({});
    setCreating(true);
  };

  const create = async () => {
    if (!form['attendanceTypeId']) {
      throw new Error('근태항목을 선택해 주세요.');
    }
    if (!form['startDate'] || !form['endDate']) {
      throw new Error('시작일과 종료일을 입력해 주세요.');
    }
    if (String(form['endDate']) < String(form['startDate'])) {
      throw new Error('종료일은 시작일보다 빠를 수 없습니다.');
    }
    await call('POST', '/attendance-requests', role, {
      attendanceTypeId: form['attendanceTypeId'],
      startDate: form['startDate'],
      endDate: form['endDate'],
      reason: form['reason'],
      changedWorkTime: form['changedWorkTime'],
      tripCategory: form['tripCategory'],
      tripPlace: form['tripPlace'],
    });
    notify('근태 신청을 등록했습니다.');
    setCreating(false);
    reload();
  };

  const cancel = async () => {
    if (!selected) {
      return;
    }
    await call('POST', `/attendance-requests/${selected['attendanceRequestId']}/cancel`, role, {});
    notify('근태 신청을 취소했습니다.');
    setSelected(null);
    reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>신청 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={data ? data.total : 0} />],
            ['이 쪽 결재대기', <Num value={countOf('결재대기')} />],
            ['이 쪽 진행중', <Num value={countOf('진행중')} />],
            ['이 쪽 승인', <Num value={countOf('승인')} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>근태 신청 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="신청자">
            <LookupSelect
              table="employee"
              role={role}
              value={draft['employeeId']}
              onChange={(v) => setDraft({ ...draft, employeeId: v })}
            />
          </Field>
          <Field label="근태항목">
            <LookupSelect
              table="attendance_type"
              role={role}
              value={draft['attendanceTypeId']}
              onChange={(v) => setDraft({ ...draft, attendanceTypeId: v })}
            />
          </Field>
          <Field label="결재 진행 상태">
            <Select
              value={draft['approvalStatus']}
              onChange={(v) => setDraft({ ...draft, approvalStatus: v })}
              options={STATUSES.map((s): [string, string] => [s, s])}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openCreate}>근태 신청</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={items}
          onRowClick={(row) => setSelected(row)}
          empty="근태 신청이 없습니다."
          columns={[
            { key: 'attendanceRequestId', label: '근태 신청 ID' },
            { key: 'employeeId', label: '신청자', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'attendanceTypeId', label: '근태항목', render: (r) => <RefName table="attendance_type" role={role} value={r['attendanceTypeId']} /> },
            { key: 'startDate', label: '시작일', render: (r) => <DateText value={r['startDate']} /> },
            { key: 'endDate', label: '종료일', render: (r) => <DateText value={r['endDate']} /> },
            { key: 'reason', label: '사유' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r['approvalStatus']} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>

      {creating ? (
        <Drawer title="근태 신청" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="신청">
            <Field label="근태항목" required>
              <LookupSelect
                table="attendance_type"
                role={role}
                value={form['attendanceTypeId']}
                onChange={(v) => setForm({ ...form, attendanceTypeId: v })}
              />
            </Field>
            <Field label="시작일" required>
              <DateInput value={form['startDate']} onChange={(v) => setForm({ ...form, startDate: v })} />
            </Field>
            <Field label="종료일" required>
              <DateInput value={form['endDate']} onChange={(v) => setForm({ ...form, endDate: v })} />
            </Field>
            <Field label="사유" wide>
              <TextInput multiline value={form['reason']} onChange={(v) => setForm({ ...form, reason: v })} />
            </Field>
            <Field label="변경 근무시간" hint="근무변경 신청일 때만 입력합니다.">
              <TextInput value={form['changedWorkTime']} onChange={(v) => setForm({ ...form, changedWorkTime: v })} />
            </Field>
            <Field label="출장·외근 구분">
              <Select
                value={form['tripCategory']}
                onChange={(v) => setForm({ ...form, tripCategory: v })}
                options={[['출장', '출장'], ['외근', '외근']]}
              />
            </Field>
            <Field label="장소">
              <TextInput value={form['tripPlace']} onChange={(v) => setForm({ ...form, tripPlace: v })} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {selected ? (
        <Drawer title="근태 신청 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['근태 신청 ID', String(selected['attendanceRequestId'])],
              ['신청자', <RefName table="employee" role={role} value={selected['employeeId']} />],
              ['근태항목', <RefName table="attendance_type" role={role} value={selected['attendanceTypeId']} />],
              ['시작일', <DateText value={selected['startDate']} />],
              ['종료일', <DateText value={selected['endDate']} />],
              ['사유', String(selected['reason'] ?? '')],
              ['결재 진행 상태', <Badge value={selected['approvalStatus']} />],
            ]}
          />
          {CANCELABLE.includes(String(selected['approvalStatus'])) ? (
            <Form onSubmit={cancel} submit="신청 취소" danger note="취소하면 결재 상태가 회수로 바뀝니다." />
          ) : null}
        </Drawer>
      ) : null}
    </div>
  );
}
